macro_rules! deps {
    () => {
        MatchPairTree!();
        FlatPat!();
        PatternExtraData!();
    };
}

macro_rules! Candidate {
    () => {
        deps!();
        # [doc = " Candidates are a generalization of (a) top-level match arms, and"] # [doc = " (b) sub-branches of or-patterns, allowing the match-lowering process to handle"] # [doc = " them both in a mostly-uniform way. For example, the list of candidates passed"] # [doc = " to [`Builder::match_candidates`] will often contain a mixture of top-level"] # [doc = " candidates and or-pattern subcandidates."] # [doc = ""] # [doc = " At the start of match lowering, there is one candidate for each match arm."] # [doc = " During match lowering, arms with or-patterns will be expanded into a tree"] # [doc = " of candidates, where each \"leaf\" candidate represents one of the ways for"] # [doc = " the arm pattern to successfully match."] # [derive (Debug)] struct Candidate < 'tcx > { # [doc = " For the candidate to match, all of these must be satisfied..."] # [doc = ""] # [doc = " ---"] # [doc = " Initially contains a list of match pairs created by [`FlatPat`], but is"] # [doc = " subsequently mutated (in a queue-like way) while lowering the match tree."] # [doc = " When this list becomes empty, the candidate is fully matched and becomes"] # [doc = " a leaf (see [`Builder::select_matched_candidate`])."] # [doc = ""] # [doc = " Key mutations include:"] # [doc = ""] # [doc = " - When a match pair is fully satisfied by a test, it is removed from the"] # [doc = "   list, and its subpairs are added instead (see [`Builder::sort_candidate`])."] # [doc = " - During or-pattern expansion, any leading or-pattern is removed, and is"] # [doc = "   converted into subcandidates (see [`Builder::expand_and_match_or_candidates`])."] # [doc = " - After a candidate's subcandidates have been lowered, a copy of any remaining"] # [doc = "   or-patterns is added to each leaf subcandidate"] # [doc = "   (see [`Builder::test_remaining_match_pairs_after_or`])."] # [doc = ""] # [doc = " Invariants:"] # [doc = " - All or-patterns ([`TestCase::Or`]) have been sorted to the end."] match_pairs : Vec < MatchPairTree < 'tcx > > , # [doc = " ...and if this is non-empty, one of these subcandidates also has to match..."] # [doc = ""] # [doc = " ---"] # [doc = " Initially a candidate has no subcandidates; they are added (and then immediately"] # [doc = " lowered) during or-pattern expansion. Their main function is to serve as _output_"] # [doc = " of match tree lowering, allowing later steps to see the leaf candidates that"] # [doc = " represent a match of the entire match arm."] # [doc = ""] # [doc = " A candidate no subcandidates is either incomplete (if it has match pairs left),"] # [doc = " or is a leaf in the match tree. A candidate with one or more subcandidates is"] # [doc = " an internal node in the match tree."] # [doc = ""] # [doc = " Invariant: at the end of match tree lowering, this must not contain an"] # [doc = " `is_never` candidate, because that would break binding consistency."] # [doc = " - See [`Builder::remove_never_subcandidates`]."] subcandidates : Vec < Candidate < 'tcx > > , # [doc = " ...and if there is a guard it must be evaluated; if it's `false` then branch to `otherwise_block`."] # [doc = ""] # [doc = " ---"] # [doc = " For subcandidates, this is copied from the parent candidate, so it indicates"] # [doc = " whether the enclosing match arm has a guard."] has_guard : bool , # [doc = " Holds extra pattern data that was prepared by [`FlatPat`], including bindings and"] # [doc = " ascriptions that must be established if this candidate succeeds."] extra_data : PatternExtraData < 'tcx > , # [doc = " When setting `self.subcandidates`, we store here the span of the or-pattern they came from."] # [doc = ""] # [doc = " ---"] # [doc = " Invariant: it is `None` iff `subcandidates.is_empty()`."] # [doc = " - FIXME: We sometimes don't unset this when clearing `subcandidates`."] or_span : Option < Span > , # [doc = " The block before the `bindings` have been established."] # [doc = ""] # [doc = " After the match tree has been lowered, [`Builder::lower_match_arms`]"] # [doc = " will use this as the start point for lowering bindings and guards, and"] # [doc = " then jump to a shared block containing the arm body."] pre_binding_block : Option < BasicBlock > , # [doc = " The block to branch to if the guard or a nested candidate fails to match."] otherwise_block : Option < BasicBlock > , # [doc = " The earliest block that has only candidates >= this one as descendents. Used for false"] # [doc = " edges, see the doc for [`Builder::match_expr`]."] false_edge_start_block : Option < BasicBlock > , }
    };
}

Candidate!();